const app=document.getElementById('toolkit-app'),stage=document.getElementById('toolkit-stage'),list=document.getElementById('toolkit-list'),search=document.getElementById('toolkit-search');
const h=(tag,props={},...kids)=>{const n=document.createElement(tag);for(const[k,v]of Object.entries(props)){if(k==='class')n.className=v;else if(k==='html')n.innerHTML=v;else if(k==='dataset')Object.assign(n.dataset,v);else if(k.startsWith('on'))n.addEventListener(k.slice(2),v);else if(v!==false&&v!=null)n.setAttribute(k,v===true?'':v)}for(const c of kids.flat())n.append(c?.nodeType?c:document.createTextNode(c));return n};
const box=(...c)=>h('div',{},...c),row=(...c)=>h('div',{class:'toolkit-row'},...c),note=t=>h('p',{class:'toolkit-note'},t);
const label=t=>h('label',{},t);
const input=(t='text',v='',p={})=>h('input',{type:t,value:v,...p});
const textarea=(v='',rows=6)=>h('textarea',{rows},v);
const select=(opts=[],v)=>h('select',{},...opts.map(o=>h('option',{value:Array.isArray(o)?o[0]:o,selected:(Array.isArray(o)?o[0]:o)===v},Array.isArray(o)?o[1]:o)));
const button=(t,fn,cls='')=>h('button',{class:cls,onclick:fn},t);
const fileIn=(accept='',multiple=false)=>h('input',{type:'file',accept,multiple});
const out=(...c)=>h('div',{class:'toolkit-output'},...c);
const progress=v=>h('progress',{max:100,value:v});
const clear=root=>{root.replaceChildren()};
const status=(root,t)=>{let n=root.querySelector('.toolkit-status');if(!n){n=h('p',{class:'toolkit-status toolkit-note'});root.append(n)}n.textContent=t;return n};
const files=f=>[...f.files||[]];
const read=(f,type='arrayBuffer')=>f[type]();
const download=(data,name)=>{const u=URL.createObjectURL(data instanceof Blob?data:new Blob([data]));const a=h('a',{href:u,download:name},'下载 '+name);a.click();setTimeout(()=>URL.revokeObjectURL(u),3000)};
const image=file=>new Promise((res,rej)=>{const u=URL.createObjectURL(file),i=new Image();i.onload=()=>{const c=h('canvas',{width:i.naturalWidth,height:i.naturalHeight});c.getContext('2d').drawImage(i,0,0);URL.revokeObjectURL(u);res(c)};i.onerror=rej;i.src=u});
const canvasBlob=(c,type='image/png',q=.9)=>new Promise(r=>c.toBlob(r,type,q));
const loadScript=src=>new Promise((res,rej)=>{if(document.querySelector(`script[src="${src}"]`))return res();const s=h('script',{src,onload:res,onerror:rej});document.head.append(s)});
const lib=(g,src)=>loadScript(src).then(()=>window[g]);
const loadPdfJs=async()=>{if(window.pdfjsLib)return window.pdfjsLib;await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';return window.pdfjsLib};
const pdfDoc=async file=>(await loadPdfJs()).getDocument({data:await read(file)}).promise;
const pdfText=async file=>{const d=await pdfDoc(file);let s='';for(let p=1;p<=d.numPages;p++){const pg=await d.getPage(p),t=await pg.getTextContent();s+=t.items.map(x=>x.str).join(' ')+'\n\n'}return s};
const pageCanvas=async(d,n,scale=2)=>{const p=await d.getPage(n),v=p.getViewport({scale}),c=h('canvas',{width:v.width,height:v.height});await p.render({canvasContext:c.getContext('2d'),viewport:v}).promise;return c};
const audioBuffer=async file=>new AudioContext().decodeAudioData(await read(file));
const wavEncode=b=>{const n=b.length,ch=b.numberOfChannels,s=new Int16Array(n*ch),ds=b.destination;for(let i=0;i<n;i++)for(let j=0;j<ch;j++){let x=Math.max(-1,Math.min(1,ds[j][i]));s[i*ch+j]=x<0?x*32768:x*32767}const u=new ArrayBuffer(44+s.length*2),v=new DataView(u),W=(o,t)=>{for(let i=0;i<t.length;i++)v.setUint8(o+i,t.charCodeAt(i))};W(0,'RIFF');v.setUint32(4,36+s.length*2,true);W(8,'WAVEfmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,ch,true);v.setUint32(24,b.sampleRate,true);v.setUint32(28,b.sampleRate*ch*2,true);v.setUint16(32,ch*2,true);v.setUint16(34,16,true);W(36,'data');v.setUint32(40,s.length*2,true);new Int16Array(u,44).set(s);return new Blob([u],{type:'audio/wav'})};
const saveCanvas=(c,name,q=.9)=>canvasBlob(c,name.endsWith('.jpg')?'image/jpeg':'image/png',q).then(b=>download(b,name));

const cats={pdf:'PDF',image:'图片',video:'视频',audio:'音频',text:'文本',calc:'计算',time:'时间',creative:'创意',ai:'AI'};
