add('pdf-to-image','PDF 转图片','pdf',r=>{const f=fileIn('application/pdf'),s=input('number','2',{min:1,max:5,step:.5}),b=button('转换并打包 ZIP',async()=>{try{const st=status(r,'解析中...'),JSZip=await lib('JSZip','https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js'),d=await pdfDoc(f.files[0]),zip=new JSZip();for(let i=1;i<=d.numPages;i++){const c=await pageCanvas(d,i,+s.value),b=await canvasBlob(c,'image/jpeg',.92);zip.file(`page-${i}.jpg`,b)}st.textContent='打包中...';download(await zip.generateAsync({type:'blob'}),'pdf-images.zip');st.textContent='完成'}catch(e){status(r,'失败：'+e.message)}},'primary');r.append(box(label('PDF 文件'),f),box(label('清晰度倍数'),s),b)},'选页导出 JPG 并打包');
