add('age-calculator','年龄计算','calc',r=>{const d=input('date','1995-01-01'),b=button('计算',()=>{const dt=new Date(d.value),ms=Date.now()-dt,y=Math.floor(ms/31557600000),next=new Date(dt);next.setFullYear(new Date().getFullYear()+1);o.replaceChildren(out(`精确年龄：${y} 岁 ${Math.floor((ms%31557600000)/(86400000*30.44))} 个月`))},'primary');r.append(box(label('出生日期'),d),b)},'年龄与生肖');

add('typing-test','打字测速','time',r=>{const samples=['the quick brown fox jumps over the lazy dog','静态页面也能承载完整的浏览器工具体验'];const target=samples[Math.floor(Math.random()*samples.length)],t=textarea('',4),st=h('div',{class:'toolkit-note'},'点击开始后输入');let startTime=Date.now();const b=button('开始',()=>{t.value='';t.focus();startTime=Date.now()},'primary');t.oninput=()=>{const sec=(Date.now()-startTime)/1000,chars=t.value.length,wpm=sec>0?Math.round(chars/5/(sec/60)):0,right=[...t.value].filter((c,i)=>c===target[i]).length;st.textContent=`${sec.toFixed(1)} 秒 / ${wpm} WPM / 准确率 ${t.value?Math.round(right/t.value.length*100):100}%`};r.append(out('目标：',target),st,label('输入'),t,b)},'WPM 与准确率');
add('stopwatch','秒表','time',r=>{const d=h('div',{style:'font-size:2.4rem;font-weight:700'},'00:00.00');let t0=0,id;const tick=()=>d.textContent=new Date(Date.now()-t0).toISOString().substr(14,9);r.append(d,row(button('开始',()=>{t0=Date.now();clearInterval(id);id=setInterval(tick,10)},'primary'),button('暂停',()=>clearInterval(id)),button('重置',()=>{clearInterval(id);d.textContent='00:00.00'})))},'毫秒与计次');
add('countdown-timer','倒计时','time',r=>{const m=input('number','5'),s=input('number','0'),d=h('div',{style:'font-size:3rem;font-weight:800'},'05:00');let id;const tick=()=>{const left=+d.dataset.left;id=left<=0?(clearInterval(id),new AudioContext(),0):(d.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`,d.dataset.left=left-1,left-1)};r.append(row(box(label('分钟'),m),box(label('秒'),s)),row(button('开始',()=>{clearInterval(id);d.dataset.left=+m.value*60+ +s.value;tick();id=setInterval(tick,1000)},'primary'),button('停止',()=>clearInterval(id))),d,note('结束时浏览器需要保持标签页打开。'))},'到零提醒');
add('world-clock','世界时钟','time',r=>{const cities={北京:'Asia/Shanghai',东京:'Asia/Tokyo',伦敦:'Europe/London',纽约:'America/New_York',洛杉矶:'America/Los_Angeles',悉尼:'Australia/Sydney'};const d=h('div',{class:'toolkit-grid'});const tick=()=>d.replaceChildren(...Object.entries(cities).map(([n,z])=>box(h('small',{},n),h('b',{},new Date().toLocaleTimeString('zh-CN',{timeZone:z})))));tick();setInterval(tick,1000);r.append(d)},'主要城市时间');
add('pomodoro-timer','番茄钟','time',r=>{const work=input('number','25'),rest=input('number','5'),d=h('div',{style:'font-size:3rem;font-weight:800'},'25:00'),p=h('div',{class:'toolkit-note'},'准备');let id,left,phase='work';const render=()=>{d.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`};const next=()=>{phase=phase==='work'?'rest':'work';left=(phase==='work'?+work.value:+rest.value)*60;p.textContent=phase==='work'?'专注中':'休息中'};const tick=()=>{left--;render();if(left<=0){next();new AudioContext()}};r.append(row(box(label('专注分钟'),work),box(label('休息分钟'),rest)),row(button('开始',()=>{clearInterval(id);phase='rest';next();render();id=setInterval(tick,1000)},'primary'),button('停止',()=>clearInterval(id))),d,p)},'专注与休息');
add('timestamp-converter','时间戳转换','time',r=>{const ts=input('number',Math.floor(Date.now()/1000)),dt=input('datetime-local','',{}),b=button('时间戳 → 日期',()=>{o1.replaceChildren(out(new Date(+ts.value*1000).toLocaleString('zh-CN')))},'primary'),b2=button('日期 → 时间戳',()=>{o1.replaceChildren(out(Math.floor(new Date(dt.value).getTime()/1000)))},'primary'),o1=out();r.append(box(label('秒级时间戳'),ts),b,box(label('本地日期'),dt),b2,o1)},'双向转换');

