const aiShell=()=>{const key=input('password'),endpoint=input('url','https://api.deepseek.com'),model=input('text','deepseek-chat'),log=out(),messages=[];const send=async prompt=>{if(!prompt.trim())return;if(!key.value){log.append(out('请先填写 API Key。'));return}messages.push({role:'user',content:prompt});log.append(box(h('b',{},'你'),h('div',{},prompt)));const busy=box(h('b',{},'AI'),h('div',{},'生成中...'));log.append(busy);try{const answer=await aiCall(messages,key.value,endpoint.value,model.value);messages.push({role:'assistant',content:answer});busy.replaceChildren(h('b',{},'AI'),h('div',{style:'white-space:pre-wrap'},answer))}catch(e){busy.replaceChildren(h('b',{},'AI'),h('div',{class:'toolkit-alert'},e.message))}};return{root:box(box(label('API Key'),key),row(box(label('接口地址'),endpoint),box(label('模型'),model)),note('Key 只保存在当前页面内存中，刷新后清空。')),log,send}};

add('unit-converter','单位换算','calc',r=>{const U={length:['m','km','cm','mi','ft','in'],mass:['kg','g','t','lb','oz'],data:['B','KB','MB','GB','TB'],area:['m2','km2','ha','ft2']},factor={m:1,km:1000,cm:.01,mi:1609.344,ft:.3048,in:.0254,kg:1,g:.001,t:1000,lb:.45359237,oz:.0283495,B:1,KB:1024,MB:1048576,GB:1073741824,TB:1099511627776,m2:1,km2:1e6,ha:1e4,ft2:.09290304},names={length:'长度',mass:'质量',data:'数据',area:'面积'},cat=select(Object.entries(names).map(([k,v])=>[k,v]),'length'),from=select(),to=select(),v=input('number','1'),res=out();const fill=()=>{from.replaceChildren(...U[cat.value].map(x=>h('option',{value:x},x)));to.replaceChildren(...U[cat.value].map(x=>h('option',{value:x},x)));to.selectedIndex=1};const calc=()=>{const a=+v.value;if(Number.isNaN(a))return;const f=cat.value==='temp'?0:factor[from.value]/factor[to.value];res.textContent=`${a} ${from.value} = ${cat.value==='temp'?a:factor[from.value]/factor[to.value]*a} ${to.value}`};cat.onchange=fill;[v,from,to].forEach(x=>x.oninput=calc);fill();calc();r.append(row(box(label('类型'),cat),box(label('输入值'),v),box(label('从'),from),box(label('到'),to)),res)},'常用单位换算');
add('percentage-calculator','百分比计算','calc',r=>{const a=input('number','20'),b=input('number','150'),k=select([['of','A 的 B% 是多少'],['is','A 是 B 的百分之几'],['change','A 到 B 的变化率']]),o=out();const calc=()=>{const x=+a.value,y=+b.value;if(!Number.isFinite(x)||!Number.isFinite(y))return;if(k.value==='of')o.textContent=`${y}% × ${x} = ${x*y/100}`;if(k.value==='is')o.textContent=y?`${x} / ${y} = ${x/y*100}%`:'除数不能为 0';if(k.value==='change')o.textContent=x?`(${y} - ${x}) / ${x} = ${(y-x)/x*100}%`:'起点不能为 0'};[a,b,k].forEach(x=>x.oninput=calc);calc();r.append(row(box(label('A'),a),box(label('B'),b),box(label('类型'),k)),o)},'占比与变化率');
add('bmi-calculator','BMI 计算','calc',r=>{const w=input('number','65',{min:1,step:.1}),hcm=input('number','170',{min:50,step:.1}),o=out();const calc=()=>{const bmi=+w.value/(+hcm.value/100)**2;if(!Number.isFinite(bmi)||bmi<=0)return;const s=bmi<18.5?'偏瘦':bmi<24?'正常':bmi<28?'超重':'肥胖';o.textContent=`BMI ${bmi.toFixed(1)}（${s}）`};[w,hcm].forEach(x=>x.oninput=calc);calc();r.append(row(box(label('体重 kg'),w),box(label('身高 cm'),hcm)),o)},'身体质量指数');
add('tip-calculator','小费计算','calc',r=>{const b=input('number','200'),p=input('number','2'),t=select([[10,'10%'],[15,'15%'],[18,'18%'],[20,'20%']],15),o=out();const calc=()=>{const tip=+b.value*+t.value/100,total=+b.value+tip,n=Math.max(1,+p.value);o.textContent=`小费 ${tip.toFixed(2)} / 总额 ${total.toFixed(2)} / 每人 ${(total/n).toFixed(2)}`};[b,p,t].forEach(x=>x.oninput=calc);calc();r.append(row(box(label('账单'),b),box(label('人数'),p),box(label('小费'),t)),o)},'账单分摊');
add('mortgage-calculator','房贷计算','calc',r=>{const p=input('number','1000000'),y=input('number','30'),rate=input('number','3.6',{step:.01}),o=out();const calc=()=>{const n=+y.value*12,mr=+rate.value/100/12,loan=+p.value;if(n<=0||loan<=0)return;const pay=mr?loan*mr/(1-(1+mr)**-n):loan/n,total=pay*n;o.textContent=`月供 ${pay.toFixed(2)} / 还款总额 ${total.toFixed(2)} / 利息 ${(total-loan).toFixed(2)}`};[p,y,rate].forEach(x=>x.oninput=calc);calc();r.append(row(box(label('贷款额'),p),box(label('年限'),y),box(label('年利率 %'),rate)),o)},'等额本息月供');
add('meeting-cost-calculator','会议成本计时','calc',r=>{const n=input('number','6',{min:1}),rate=input('number','120',{min:0,step:.01}),d=h('div',{style:'font-size:3rem;font-weight:800'},'0.00');let id,start=0;const tick=()=>{const mins=(Date.now()-start)/60000,cost=mins*+n.value*+rate.value;d.textContent=cost.toFixed(2)};r.append(row(box(label('人数'),n),box(label('人均小时成本'),rate)),row(button('开始',()=>{clearInterval(id);start=Date.now();tick();id=setInterval(tick,1000)},'primary'),button('停止',()=>clearInterval(id))),d,note('按会议进行时长实时累计。'))},'会议烧钱提醒');
add('ai-trajectory','AI 路径推演','ai',r=>{const a=aiShell(),now=textarea('当前状态：一名大三学生，会一点前端和写作。',4),goal=input('text','一年内做出有作品集的远程工作'),limit=input('text','每周可投入 15 小时'),b=button('推演三条路径',()=>a.send(`请根据下面信息推演三条可行路径。每条路径给出目标、关键动作、第一周任务、主要风险和判断信号。用简体中文。\n\n现状：${now.value}\n目标：${goal.value}\n约束：${limit.value}`),'primary');r.append(a.root,box(label('现状'),now),row(box(label('目标'),goal),box(label('约束'),limit)),b,a.log)},'多路径决策草稿');
add('ai-tarot','AI 塔罗','ai',r=>{const CARDS=['愚者','魔术师','女祭司','皇后','皇帝','教皇','恋人','战车','力量','隐士','命运之轮','正义','倒吊人','死神','节制','恶魔','塔','星星','月亮','太阳','审判','世界'],a=aiShell(),question=input('text','最近适合专注哪件事？'),draw=out(),b=button('抽取三张牌',()=>{const xs=[...CARDS].sort(()=>Math.random()-.5).slice(0,3),items=xs.map(x=>[x,Math.random()<.5?'正位':'逆位']);draw.replaceChildren(...items.map(([n,p])=>box(h('b',{},n),h('div',{},p))));const text=items.map(([n,p])=>`${n}（${p}）`).join('、');return a.send(`你是温和、不宿命论的塔罗解读助手。问题：${question.value}。请基于三张牌给出连贯解读：现状、挑战、建议；不要做医疗、法律或投资决定；用简体中文。牌面：${text}`)},'primary');r.append(a.root,box(label('问题'),question),b,draw,a.log)},'大阿卡纳三牌阵');
add('ex-ai-chat','AI 情绪梳理','ai',r=>{const a=aiShell(),t=textarea('',4),b=button('发送',()=>a.send(t.value),'primary');a.messages.push({role:'system',content:'你是一个帮助用户梳理人际与情绪的倾听者。语气稳定、尊重边界，不复刻真实具体人物，不操纵、不评判，也不提供医疗或法律决定。请用简体中文，先确认感受，再帮助用户看清需求，最后给一个小练习。'});t.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();a.send(t.value);t.value=''}};b.onclick=()=>{a.send(t.value);t.value=''};r.append(a.root,note('这个工具只用于情绪梳理，不替代心理咨询；AI 不代表任何真实他人。'),label('想说什么'),t,b,a.log)},'安全表达练习');
add('ai-text-adventure','AI 文字冒险','ai',r=>{const a=aiShell(),scene=out(h('div',{style:'white-space:pre-wrap'},'你在一座雾中的天文台醒来，桌上有一张半烧毁的星图。')),t=input('text','查看星图'),b=button('行动',()=>{const x=t.value;if(!x)return;a.send(`玩家行动：${x}。请继续 2-4 段第二人称冒险，结尾给 3 个短行动选项，不要替玩家决定。`)},'primary');a.messages.push({role:'system',content:'你是文字冒险主持人。世界一致、悬念适度、不出现血腥残酷细节；每回合 2-4 段，用简体中文；结尾列 3 个行动选项。'});r.append(a.root,scene,label('你的行动'),t,b,a.log)},'分支故事生成');

const findTool=()=>location.hash.match(/^#\/tool\/([\w-]+)/)?.[1];
const renderList=()=>{const q=search.value.trim().toLowerCase();list.replaceChildren();Object.entries(cats).forEach(([cat,title])=>{const items=T.filter(x=>x.cat===cat&&(!q||`${x.title} ${x.desc} ${x.id}`.toLowerCase().includes(q)));if(!items.length)return;list.append(h('h3',{style:'margin:12px 0 6px;font-size:.92rem'},title),...items.map(x=>h('a',{class:'toolkit-link',href:`#/tool/${x.id}`,'aria-current':findTool()===x.id?'page':undefined},h('b',{},x.title),h('span',{},x.desc))))})};
const renderHome=()=>{stage.replaceChildren(h('h2',{},'工具总览'),h('p',{class:'toolkit-note'},`${T.length} 项功能，全部在当前页面内运行；AI 工具需要你自行填写 API Key。`),h('div',{class:'toolkit-grid'},...Object.entries(cats).map(([cat,title])=>h('a',{class:'toolkit-link',href:`#/tool/${T.find(x=>x.cat===cat).id}`,style:'border:1px solid var(--border)'},h('b',{},title),h('span',{},`${T.filter(x=>x.cat===cat).length} 项`)))))};
const renderTool=tool=>{const body=out();stage.replaceChildren(body);try{tool.render(body)}catch(e){body.append(h('p',{class:'toolkit-alert'},`加载失败：${e.message}`))}};
const singleTool=app?.dataset?.tool;
if(singleTool){renderTool(T.find(x=>x.id===singleTool))}
else{const route=()=>{renderList();const id=findTool(),tool=T.find(x=>x.id===id);if(!tool){renderHome();return}stage.replaceChildren(h('h2',{},tool.title),h('p',{class:'toolkit-note'},tool.desc));renderTool(tool);window.scrollTo({top:0,behavior:'smooth'})};search.oninput=renderList;addEventListener('hashchange',route);route()}
